#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-$HOME/visionone-bank-demo}"
BRANCH="bam-banking-ui"
STABLE_UI_COMMIT="ce60ff6840b10dd95ff2c847dd4cfd761906e621"
VERSION="2.2.1"
IMAGE="bambank-demo:v57"
CONTAINER="bambank-demo-v57"
PORT="8081"

log() {
  printf '\n\033[1;34m==> %s\033[0m\n' "$*"
}

die() {
  printf '\n\033[1;31mERROR: %s\033[0m\n' "$*" >&2
  exit 1
}

for command_name in git docker python3 curl base64; do
  command -v "$command_name" >/dev/null 2>&1 || die "$command_name is not installed"
done

[[ -d "$ROOT/.git" ]] || die "Git repository not found: $ROOT"
[[ -f "$ROOT/.env" ]] || die "Project .env not found: $ROOT/.env"
[[ -f /usr/local/bin/tmas ]] || die "TMAS binary not found: /usr/local/bin/tmas"

cd "$ROOT"

log "Preparing revision 57"
git fetch origin --prune
git checkout "$BRANCH"

if [[ -n "$(git status --porcelain --untracked-files=no)" ]]; then
  die "Tracked files have uncommitted changes. Commit or stash them first."
fi

git cat-file -e "${STABLE_UI_COMMIT}^{commit}" 2>/dev/null || die "Approved UI baseline is unavailable"

log "Applying the approved design baseline for revision 57"
for file in app/main.py app/static/index.html app/static/app.js app/static/styles.css; do
  git show "${STABLE_UI_COMMIT}:$file" > "$file"
done

log "Applying the pending v55 visual refinements"
base64 -d > /tmp/apply_bam_revision_v55.py <<'V55_B64'

V55_B64
python3 /tmp/apply_bam_revision_v55.py "$ROOT"

log "Adding Vision One Live without replacing the existing scanner layout"
base64 -d > app/vision_one_live.py <<'BACKEND_B64'

BACKEND_B64

base64 -d > /tmp/apply_bam_v57_patch.py <<'PATCHER_B64'

PATCHER_B64
python3 /tmp/apply_bam_v57_patch.py "$ROOT"

log "Validating source"
python3 -m py_compile app/main.py app/vision_one_live.py
git diff --check

if docker image inspect node:22-alpine >/dev/null 2>&1; then
  docker run --rm -v "$ROOT/app/static:/work:ro" node:22-alpine node --check /work/app.js
else
  echo "node:22-alpine is not cached; JavaScript validation skipped."
fi

log "Building revision 57"
docker build --no-cache -t "$IMAGE" .

log "Stopping the previous BAM Bank container"
OLD_IDS="$(docker ps -q --filter "publish=$PORT" 2>/dev/null || true)"
if [[ -n "$OLD_IDS" ]]; then
  docker rm -f $OLD_IDS
fi

for name in bambank-demo-v56 bambank-demo-restored visionone-bank-demo-test "$CONTAINER"; do
  docker rm -f "$name" >/dev/null 2>&1 || true
done

docker volume create bambank-demo-data >/dev/null

TMAS_ENV_ARGS=()
if [[ -f "$HOME/.tmas/.env" ]]; then
  TMAS_ENV_ARGS=(
    -v "$HOME/.tmas/.env:/run/secrets/tmas.env:ro"
    -e "TMAS_ENV_FILE=/run/secrets/tmas.env"
  )
else
  TMAS_ENV_ARGS=(-e "TMAS_ENV_FILE=")
fi

log "Starting revision 57"
docker run -d \
  --name "$CONTAINER" \
  --restart unless-stopped \
  -p "$PORT:8080" \
  --env-file "$ROOT/.env" \
  -e "TMAS_BINARY=/usr/local/bin/tmas" \
  -e "TMAS_REGION=ap-southeast-1" \
  -e "AI_SCANNER_TARGET_BASE_URL=http://127.0.0.1:8080" \
  -e "AI_SCANNER_RUNTIME_DIR=/tmp/bambank-aiscan" \
  -e "AI_SCANNER_MAX_SECONDS=900" \
  -v "/usr/local/bin/tmas:/usr/local/bin/tmas:ro" \
  -v "bambank-demo-data:/data" \
  "${TMAS_ENV_ARGS[@]}" \
  --read-only \
  --tmpfs "/tmp:size=128m,mode=1777" \
  --security-opt "no-new-privileges:true" \
  "$IMAGE" >/dev/null

log "Validating deployment"
HEALTH=""
for _ in $(seq 1 40); do
  if HEALTH="$(curl -fsS "http://127.0.0.1:$PORT/api/health" 2>/dev/null)"; then
    DEPLOYED_VERSION="$(printf '%s' "$HEALTH" | python3 -c 'import json,sys; print(json.load(sys.stdin).get("version",""))')"
    if [[ "$DEPLOYED_VERSION" == "$VERSION" ]]; then
      break
    fi
  fi
  sleep 1
done

[[ -n "$HEALTH" ]] || {
  docker logs --tail=100 "$CONTAINER" || true
  die "Application did not become healthy"
}

DEPLOYED_VERSION="$(printf '%s' "$HEALTH" | python3 -c 'import json,sys; print(json.load(sys.stdin).get("version",""))')"
[[ "$DEPLOYED_VERSION" == "$VERSION" ]] || {
  docker logs --tail=100 "$CONTAINER" || true
  die "Expected version $VERSION, received $DEPLOYED_VERSION"
}

log "Committing revision 57"
mkdir -p scripts
cp "$0" scripts/apply_bam_revision_v57_all_in_one.sh
chmod +x scripts/apply_bam_revision_v57_all_in_one.sh

git add \
  app/main.py \
  app/vision_one_live.py \
  app/static/index.html \
  app/static/app.js \
  app/static/styles.css \
  scripts/apply_bam_revision_v57_all_in_one.sh

git diff --cached --check

if ! git diff --cached --quiet; then
  git commit -m "Apply BAM Bank revision 57"
fi

git push origin "$BRANCH"
git branch --set-upstream-to="origin/$BRANCH" "$BRANCH" >/dev/null

log "Revision 57 completed"
echo "Version   : $VERSION"
echo "Branch    : $BRANCH"
echo "Commit    : $(git log -1 --oneline)"
echo "Container : $CONTAINER"
echo "Health    : $HEALTH"
echo
echo "Open Presenter Security Lab -> AI Scanner -> Custom prompts."
echo "Use Demo for Test in app or Vision One Live for the TMAS scan."
